import { test } from 'node:test';
import assert from 'node:assert/strict';
import { JOBS } from '../src/jobs/index.js';

// #9, #12: the 500 body is shown on the scheduler's admin screen, so it must not carry
// the internal error text (CONTRIBUTING.md). This checks every job in JOBS, including
// ones added later, instead of one job at a time.
const SECRET = 'db down at 10.0.0.5';

// A db where every method throws, whatever the job calls.
const brokenDb = new Proxy({}, {
  get: () => () => { throw new Error(SECRET); },
});

for (const [name, job] of Object.entries(JOBS)) {
  test(`${name}: the 500 body is the fixed message, without the internal error text`, () => {
    const res = job.run({ db: brokenDb, email: 'a@example.com' });
    assert.equal(res.status, 500);
    assert.equal(res.body.error, 'internal error');
    assert.doesNotMatch(JSON.stringify(res.body), /db down|10\.0\.0\.5/);
  });
}
