import { test } from 'node:test';
import assert from 'node:assert/strict';
import { run } from '../src/jobs/rollup.js';

test('rollup: rolls up yesterday', () => {
  const res = run({ db: { rollupYesterday: () => 120 } });
  assert.equal(res.status, 200);
  assert.equal(res.body.rows, 120);
});

// The 500 body is shown on the scheduler's admin screen; it must not carry the internal error text (CONTRIBUTING.md).
test('rollup: a database error is a 500 with a fixed message', () => {
  const res = run({ db: { rollupYesterday: () => { throw new Error('db down at 10.0.0.5'); } } });
  assert.equal(res.status, 500);
  assert.equal(res.body.error, 'internal error');
  assert.doesNotMatch(JSON.stringify(res.body), /db down|10\.0\.0\.5/);
});

